import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d as h,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"刻蚀偏置与 OPC 回环","description":"","frontmatter":{"title":"刻蚀偏置与 OPC 回环","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etch-bias-opc-loop.md","filePath":"litho/etch-bias-opc-loop.md","lastUpdated":1789023840000}'),A={name:"litho/etch-bias-opc-loop.md"};function c(d,a,P,C,I,_){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="刻蚀偏置与-opc-回环" tabindex="-1">刻蚀偏置与 OPC 回环 <a class="header-anchor" href="#刻蚀偏置与-opc-回环" aria-label="Permalink to &quot;刻蚀偏置与 OPC 回环&quot;">​</a></h1><div class="epigraph"><p>ADI 贴目标之后，腔体还要把边再挪一截；这截偏置该回写进 OPC 版本，而不是每个班次拿 AEI 去拧扫描机剂量。</p><footer>—— 对照 ADI/AEI 偏置、紧凑刻蚀核与 run-to-run 的分工；Levinson 对 after-etch 计量的区分</footer></div><p><a href="/litho/etch-loading-effect">上一课</a>把负载写成布局邻域。缺口是闭环：在线 AEI 看见偏置漂了，谁改、改哪一层模型。<a href="/litho/etch-in-opc">刻蚀进 OPC</a> 与 <a href="/litho/etch-model-calibration">刻蚀模型校准</a> 已写核如何进迭代、如何标定；本课钉<strong>量产回环</strong>：何时重拟合核、何时只调平均偏置、何时重工晶圆。CMP 形貌如何先毁掉焦深，留给[下一课](/litho/cmp-topography）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>偏置 = AEI − ADI（同一部位）。它随腔体老化、聚合物积累、硬掩模厚度和开口率漂。<a href="/litho/adi-aei">ADI/AEI</a> 已要求两套控制图。回环错误形态：用 AEI 误差去改扫描机剂量——把刻蚀指纹写进光学，下层套刻和胶窗一起坏。正确分层：扫描机盯 ADI；刻蚀 APC 盯平均速率/偏置；密度形状的变化才触发 OPC 核重标定。</p><p>缺口是<strong>版本与频率</strong>，不是再拟合一次核。每片重 OPC 不可能；每季度重标定可能太慢。中间是偏置偏移量（global etch bias）进 APC，形状残差进工程触发器。</p><h3 id="回环不是实时-ilt" tabindex="-1">回环不是实时 ILT <a class="header-anchor" href="#回环不是实时-ilt" aria-label="Permalink to &quot;回环不是实时 ILT&quot;">​</a></h3><p>在线数据稀疏、有计量延迟、有抽样偏差（下一门过程控制会展开）。只能更新低维参数：全场平均、径向一次项，或许分密度档。二维 jog 的核形状仍靠工程实验片。把稀疏 AEI 直接当全芯片目标去反演 OPC，会拟合噪声。</p><p><span class="marginnote">OPC 版本号含刻蚀食谱 id 与核版本。腔体大保养后应走验证矩阵，而不是假定偏置连续可滑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：成对或对齐的 ADI/AEI、开口率图。决策树：平均偏置漂 → 刻蚀时间/过刻 APC；径向指纹 → 腔体匹配；密度斜率变 → 重采集校准片、更新核；局部新热点 → LRC/PWQ，可能改设计。与后课 APC、R2R 的关系：本课定义光刻–刻蚀分工；控制课写滤波与抽样。</p><p>仿真链：更新核后必须重跑关键层 LRC，不能只改表格里一个数。</p><p>触发器要数字化：密度斜率相对校准片偏多少、新热点是否只在一种开口率出现。含糊的「感觉偏了就重 OPC」会把核版本刷爆。SEMI 意义上的过程控制把低维更新和模型重辨识分开，本课沿用这道缝。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平均偏置对应全球中性/离子水平；密度斜率对应微负荷与钝化。前者可周频更新，后者是模型结构。扫描机剂量主要动 ADI 均值，对刻蚀密度斜率几乎无能为力。故「AEI 偏了就加剂量」会在密孤立差上越补越歪。</p>',15)),(e(),s(E,null,{default:o(()=>[p(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20AEI%5B%22%E5%9C%A8%E7%BA%BF%20AEI%22%5D%20--%3E%20SPLIT%5B%22%E5%88%86%E5%B1%82%22%5D%0A%20%20SPLIT%20--%3E%20APC%5B%22%E5%B9%B3%E5%9D%87%E5%81%8F%E7%BD%AE%20%E2%86%92%20%E5%88%BB%E8%9A%80%20APC%22%5D%0A%20%20SPLIT%20--%3E%20CH%5B%22%E5%BE%84%E5%90%91%E6%8C%87%E7%BA%B9%20%E2%86%92%20%E8%85%94%E4%BD%93%22%5D%0A%20%20SPLIT%20--%3E%20OPC%5B%22%E5%AF%86%E5%BA%A6%E6%96%9C%E7%8E%87%20%E2%86%92%20%E6%A0%B8%E7%89%88%E6%9C%AC%22%5D%0A%20%20ADI%5B%22ADI%22%5D%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E5%89%82%E9%87%8F%20%2F%20%E7%84%A6%E7%82%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 OPC 当每片控制环。不重写等离子体第一性原理。金属–via enclosure 的 AEI 目标属于此环的规格，不要改成 ADI 目标。</p><p>后课默认：偏置分层回写；扫描机不背刻蚀的锅。下一课形貌来自 CMP，它会先改焦点和对准，再改下一层的光学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>刻蚀偏置回环分层：均值进 APC，形状进核版本，禁止用 AEI 拧剂量。</li><li>OPC 版本绑定食谱；大保养后重验证。</li><li>稀疏计量只能更新低维参数。</li><li>出处：ADI/AEI 与计算光刻刻蚀核通称；Levinson 计量区分。</li></ul>',5))])}const m=r(A,[["render",c]]);export{f as __pageData,m as default};
